#include <cstddef>
#include <cstdint>
#include <array>
namespace { constexpr std::size_t MAX_COUNT=64; int lower_ascii(int c){return c>='A'&&c<='Z'?c+32:c;} bool less(const std::int64_t*v,const std::array<std::size_t,MAX_COUNT>&o,const std::array<std::size_t,MAX_COUNT>&l,const std::array<std::size_t,MAX_COUNT>&p,std::size_t a,std::size_t b){auto lim=p[a]<p[b]?p[a]:p[b];for(std::size_t i=0;i<lim;i++){int x=lower_ascii(v[o[a]+i]),y=lower_ascii(v[o[b]+i]);if(x!=y)return x<y;}if(p[a]!=p[b])return p[a]<p[b];auto sa=l[a]-p[a],sb=l[b]-p[b];if(!sa||!sb)return sa<sb;std::size_t za=0,zb=0;while(za<sa&&v[o[a]+p[a]+za]=='0')za++;while(zb<sb&&v[o[b]+p[b]+zb]=='0')zb++;auto na=sa-za,nb=sb-zb;if(na!=nb)return na<nb;for(std::size_t i=0;i<na;i++){auto x=v[o[a]+p[a]+za+i],y=v[o[b]+p[b]+zb+i];if(x!=y)return x<y;}return false;} }
extern "C" std::int64_t natural_sort(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<1||n>4161||v[0]<0||v[0]>64)return -1;auto count=static_cast<std::size_t>(v[0]);std::array<std::size_t,64>o{},l{},p{},order{};std::size_t cursor=1,total=0;for(std::size_t i=0;i<count;i++){if(cursor>=n||v[cursor]<0||v[cursor]>64)return -1;l[i]=v[cursor++];o[i]=cursor;p[i]=l[i];bool digit=false;for(std::size_t j=0;j<l[i];j++){auto c=v[cursor+j];if(c>='0'&&c<='9'){if(j==0)return -1;if(!digit){p[i]=j;digit=true;}}else if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z'))||digit)return -1;}cursor+=l[i];total+=l[i];order[i]=i;}if(cursor!=n)return -1;for(std::size_t i=1;i<count;i++){auto item=order[i];auto j=i;while(j>0&&less(v,o,l,p,item,order[j-1])){order[j]=order[j-1];--j;}order[j]=item;}auto bytes=total+(count?count-1:0);if(bytes>cap||(bytes&&!out))return -2;std::size_t w=0;for(std::size_t i=0;i<count;i++){if(i)out[w++]='\n';auto k=order[i];for(std::size_t j=0;j<l[k];j++)out[w++]=static_cast<std::uint8_t>(v[o[k]+j]);}return static_cast<std::int64_t>(w);}
